import{_ as n,l as t,o as a,c as d,v as o,p as s,x as c,d as l,i,S as f}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"内存序指令 fence","description":"","frontmatter":{"title":"内存序指令 fence","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fence-instructions.md","filePath":"cs/fence-instructions.md","lastUpdated":1789023840000}'),h={name:"cs/fence-instructions.md"};function p(A,e,E,u,_,m){const r=t("Mermaid");return a(),d("div",null,[e[1]||(e[1]=o('<h1 id="内存序指令-fence" tabindex="-1">内存序指令 fence <a class="header-anchor" href="#内存序指令-fence" aria-label="Permalink to &quot;内存序指令 fence&quot;">​</a></h1><div class="epigraph"><p>弱序机器上，store 后面的 load 可以先执行；fence 告诉硬件哪些程序序必须变成对其他核可见的序，原子指令的 acquire/release 是它的特化。</p><footer>—— 据 The RISC-V Instruction Set Manual；ARM ARM；Intel SDM；Adve and Gharachorloo, Shared Memory Consistency Models, IEEE Computer 1996 整理</footer></div><p><a href="/cs/lr-sc-cas">上一课</a>给出 RMW。<a href="/cs/dma-scatter-gather">DMA</a> 要求描述符写对设备可见。<a href="/cs/nvm-persistent">持久内存</a> 还要冲刷。缺口是 CPU 之间的 <strong>内存一致性模型与 fence</strong>：x86 近似 TSO，ARM/RISC-V 更弱。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>乱序核与写缓冲让独立地址的访问重排。若核0 store 数据再 store 就绪标志，核1 load 标志再 load 数据，弱序上可能看见新标志旧数据。fence（RISC-V <code>fence</code>，ARM <code>dmb</code>/<code>dsb</code>，x86 <code>mfence</code>/<code>sfence</code>/<code>lfence</code> 及 <code>lock</code> 副作用）切开。缺口不是 CAS 循环写法，而是<strong>哪些重排被禁止</strong>。</p><p>TSO（x86）：允许 store-load 重排为主，程序员少插 fence；仍要 <code>mfence</code> 于少数模式。ARM/RV：要显式 acquire/release 或 fence。C/C++ 的 <code>memory_order</code> 降到这些指令。</p><h3 id="fence-不是「刷新-cache」" tabindex="-1">fence 不是「刷新 cache」 <a class="header-anchor" href="#fence-不是「刷新-cache」" aria-label="Permalink to &quot;fence 不是「刷新 cache」&quot;">​</a></h3><p>它不把缓存丢掉，而是约束提交与可见性序。<code>clflush</code> 才冲缓存行（持久与 DMA 有时要）。把 <code>fence</code> 当 <code>wbinvd</code>，性能与语义都错。设备 MMIO 往往需要更强的 I/O 围栏，以防写缓冲合并门铃。</p><p><span class="marginnote">Adve/Gharachorloo 1996 是模型综述。RISC-V 手册第 14 章一类（版本因手册而变）描述 fence 前趋。ARM ARM 的 barrier。Intel SDM 的 MFENCE。本课不发明论文号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>生产者：写 payload，<code>release</code> store 或 <code>fence rw,w</code> 再写 flag。消费者：读 flag，<code>acquire</code> 或 <code>fence r,rw</code> 再读 payload。RISC-V <code>fence.i</code> 管指令缓存，是另一条（自修改代码）。PCIe DMA：写描述符后可能要 store-release 再写门铃 MMIO。</p>',11)),(a(),s(f,null,{default:c(()=>[i(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22store%20%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20REL%5B%22release%20%2F%20fence%22%5D%0A%20%20REL%20--%3E%20FG%5B%22store%20%E6%A0%87%E5%BF%97%22%5D%0A%20%20FG%20--%3E%20ACQ%5B%22acquire%20%2F%20fence%22%5D%0A%20%20ACQ%20--%3E%20LD%5B%22load%20%E6%95%B0%E6%8D%AE%22%5D%0A%20%20LD%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ASIMD%20%E4%B8%8D%E6%94%B9%E5%8F%98%E8%BF%99%E5%A5%97%E5%BA%8F%E7%9A%84%E5%AF%B9%E8%B1%A1%22%5D%0A"})]),fallback:c(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>与单核：编译器重排也要编译器屏障；本课偏硬件指令。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下一课 SIMD 并行的是数据通路，内存序仍按标量模型作用于每条向量访存（实现可更宽）。RVV 的向量 load 同样受 fence 约束。本课把 ISA 对照从「运算」接到「多核可见性」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 C++ 标准逐条背完，不证明 RCpc vs RCsc。不写 GPU 的 <code>__threadfence</code>。不进入 JVM 内存模型全书。</p><p>后课默认：弱序 ISA 用 fence/acquire-release 配对生产者消费者；x86 TSO 更强但仍非顺序一致。下一课 SIMD 扩展。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>弱序允许重排；fence 切开可见性。</li><li>不是冲缓存；DMA/MMIO 常需更强序。</li><li>x86 TSO vs ARM/RV 弱序决定 fence 密度。</li><li>出处：RISC-V ISA；ARM ARM；Intel SDM；Adve and Gharachorloo, 1996。</li></ul>',8))])}const I=n(h,[["render",p]]);export{S as __pageData,I as default};
